class Solution {
public:
    bool containsDuplicate(vector<int>& nums) {
        unordered_set<int> seen;
        seen.reserve(nums.size());
        for (int x : nums) {
            if (seen.find(x) != seen.end()) {
                return true;
            }
            seen.insert(x);
        }
        return false;
    }
};
